    <div class="invoice-parties"><div class="invoice-card"><div class="invoice-card-title">Laskutettava</div><strong><?=h($inv['customer_name']?:'—')?></strong><?php if($inv['customer_address']):?><div><?=nl2br(h($inv['customer_address']))?></div><?php endif;?><?php if($inv['customer_business_id']):?><div>Y-tunnus <?=h($inv['customer_business_id'])?></div><?php endif;?><?php if($inv['customer_email']):?><div><?=h($inv['customer_email'])?></div><?php endif;?></div><div class="invoice-card"><div class="invoice-card-title">Työ / ajoneuvo</div><strong><?=h(trim(($inv['reg_plate']?:$inv['nickname']).' · '.$inv['make'].' '.$inv['model']))?></strong><div><?=h($inv['title'])?></div><div><?=h(fiDate($inv['service_date']))?> · <?=h(recordedKm((int)$inv['odometer']))?></div></div></div>
